"""Pydantic schemas for Gemini Structured Outputs.

Enforces strict JSON schema generation and deterministic structural parsing.
"""
from __future__ import annotations

from typing import Literal
from pydantic import BaseModel, Field


class EditorialPickSchema(BaseModel):
    """Schema for a single editorial decision generated by Gemini."""
    article_ids: list[str] = Field(
        description="List of candidate article IDs that support this story from the input candidate list."
    )
    score: int = Field(
        ge=0,
        le=100,
        description="Editorial significance score (0-100) reflecting audience relevance, newsworthiness, and viral potential.",
    )
    kind: Literal["NEW", "UPDATE", "DUPLICATE", "IGNORE"] = Field(
        description="'NEW' for first-time stories, 'UPDATE' for significant developments, 'DUPLICATE' for repeat reporting, 'IGNORE' for unsuitable/routine items."
    )
    verification_status: Literal[
        "OFFICIAL_CONFIRMATION",
        "FIRST_PARTY_STATEMENT",
        "REPUTABLE_REPORTING",
        "ATTRIBUTED_CLAIM",
        "UNVERIFIED_RUMOR",
        "SPECULATION",
    ] = Field(
        default="REPUTABLE_REPORTING",
        description="Factual verification confidence status."
    )
    parent_story_id: str = Field(
        default="",
        description="Exact story_id from previously_alerted if kind is 'UPDATE' or 'DUPLICATE', else empty string.",
    )
    development_tr: str = Field(
        default="",
        description="Concrete factual new information in Turkish if kind is 'UPDATE', else empty string.",
    )
    headline_tr: str = Field(
        min_length=5,
        max_length=200,
        description="Clean, impactful, factual Turkish headline.",
    )
    cover_title_tr: str = Field(
        default="",
        max_length=150,
        description="Punchy 3-8 word cover title / visual hook for Instagram post or Reel cover image.",
    )
    caption_idea_tr: str = Field(
        default="",
        max_length=800,
        description="Draft Instagram caption in Turkish (engaging, informative, natural tone).",
    )
    relevance_reason_tr: str = Field(
        default="",
        max_length=500,
        description="Explicit editorial reason explaining relevance to @efsomagazin audience or reason for rejection.",
    )
    why_efso_tr: str = Field(
        default="",
        max_length=500,
        description="Short reason why this story fits @efsomagazin's pop-culture identity or why it should/should not be posted.",
    )
    uncertainties_tr: str = Field(
        default="",
        max_length=500,
        description="Notes on unverified claims, rumors, or required editorial verification checks.",
    )
    suggested_format: Literal["POST", "CAROUSEL", "REEL"] = Field(
        default="POST",
        description="Recommended Instagram content format."
    )
    category: Literal["GLOBAL", "YERLI", "VIRAL", "MUZIK_DIZI", "INTERNET"] = Field(
        default="GLOBAL",
        description="Editorial content category."
    )


class EditorialDecisionBatch(BaseModel):
    """Batch of editorial picks returned by Gemini."""
    picks: list[EditorialPickSchema] = Field(
        default_factory=list,
        description="Selected editorial stories. Empty list if no candidate meets the high threshold.",
    )
    run_editorial_summary_tr: str = Field(
        default="",
        description="Brief 1-2 sentence executive summary of news scan in Turkish."
    )


class DiagnosticArticleDecision(BaseModel):
    """Compact structured evaluation decision for a single candidate article."""
    article_id: str = Field(
        description="Exact 24-character candidate article ID from the input candidates list."
    )
    score: int = Field(
        ge=0,
        le=100,
        description="Editorial interest score from 0 to 100 reflecting audience relevance, visual appeal, fan engagement, and viral potential.",
    )
    disposition: Literal["DIGEST", "RESERVE", "IGNORE", "HOLD", "SENSITIVE_REVIEW"] = Field(
        description="'DIGEST' for editorially approved stories, 'RESERVE' for optional/filler backlog buffer, 'IGNORE' for unsuitable/routine/negative items, 'HOLD' for verification-needed claims, 'SENSITIVE_REVIEW' for significant sensitive tragedy/death news needing private review.",
    )
    kind: Literal["NEW", "UPDATE", "DUPLICATE"] = Field(
        default="NEW",
        description="'NEW' for first-time stories, 'UPDATE' for significant developments, 'DUPLICATE' for repeat reporting.",
    )
    urgency: Literal["NORMAL", "BREAKING"] = Field(
        default="NORMAL",
        description="'NORMAL' for standard digest delivery, 'BREAKING' for rare, major breaking alerts.",
    )
    rationale_tr: str = Field(
        min_length=5,
        max_length=300,
        description="Brief, grounded editorial rationale in Turkish explaining the score and disposition.",
    )
    headline_tr: str = Field(
        default="",
        max_length=200,
        description="Short, impactful Turkish headline for editorially selected stories (DIGEST/RESERVE/BREAKING), empty string for IGNORE.",
    )
    verification_status: Literal[
        "OFFICIAL_CONFIRMATION",
        "FIRST_PARTY_STATEMENT",
        "REPUTABLE_REPORTING",
        "ATTRIBUTED_CLAIM",
        "UNVERIFIED_RUMOR",
        "SPECULATION",
    ] = Field(
        default="REPUTABLE_REPORTING",
        description="Factual verification confidence status.",
    )


class DiagnosticEvaluationBatch(BaseModel):
    """Explicit per-article diagnostic evaluation batch requiring exactly one decision per candidate."""
    decisions: list[DiagnosticArticleDecision] = Field(
        default_factory=list,
        description="List of explicit decisions containing exactly one decision per input candidate article ID.",
    )
    run_editorial_summary_tr: str = Field(
        default="",
        max_length=500,
        description="Brief 1-2 sentence executive summary of news scan in Turkish.",
    )

